// Kotlin bindings (UniFFI) + JNI libraries for crates/guardedsleep-core.
// Generated by `scripts/core-build.sh android`; both outputs are gitignored.
plugins {
    alias(libs.plugins.android.library)
}

android {
    namespace = "org.guardedsleep.core"
    compileSdk = 37

    defaultConfig {
        minSdk = 26
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    testOptions {
        unitTests.all {
            // Golden vectors shared with the Rust and WASM test suites.
            it.systemProperty(
                "conformance.vectors",
                rootProject.file("../../crates/guardedsleep-core/vectors/conformance.json").absolutePath,
            )
            // gs-trace/1 documents replayed through the binding (ADR-016, AC-9).
            it.systemProperty(
                "conformance.traces",
                rootProject.file("../../crates/guardedsleep-core/vectors/traces").absolutePath,
            )
            // Host build of the core from `scripts/core-build.sh android` (AGP drops .so files
            // from unit-test resources, so JNA gets the directory directly).
            it.systemProperty("jna.library.path", rootProject.file("../../target/debug").absolutePath)
        }
    }
}

kotlin {
    jvmToolchain(21)
    compilerOptions { jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17) }
}

dependencies {
    implementation("${libs.jna.get()}@aar")
    testImplementation(libs.jna)
    testImplementation(libs.junit)
    testImplementation(libs.json)
}
